from taf.sw.dcap.rd.schemas.base import SchemaField, SchemaObject


class StartTraceV1(SchemaObject):
    duration = SchemaField(name="duration", not_null=True)
    tracer_id = SchemaField(name="id", not_null=True)
    start_time = SchemaField(name="start_time", not_null=True)
    status = SchemaField(name="status", not_null=True)
    tag = SchemaField(name="tag", not_null=True)
    targets = SchemaField(name="targets", not_null=True)

    def __init__(self, duration=None, tracer_id=None, start_time=None, status=None, tag=None, targets=None):
        self.duration = duration
        self.tracer_id = tracer_id
        self.start_time = start_time
        self.status = status
        self.tag = tag
        self.targets = targets

        super(StartTraceV1, self).__init__()
